import torch


def _resolve_dtype(d):
    if isinstance(d, torch.dtype):
        return d
    return getattr(torch, str(d).replace("torch.", ""))


def run(inp, target, weight, reduction):
    ref_inp = inp.to(torch.float64)
    ref_target = target.to(torch.float64)
    ref_weight = weight.to(torch.float64)
    return torch.binary_cross_entropy_with_logits(ref_inp, ref_target, weight=ref_weight, reduction=reduction)


def gen_inputs(ctx, device):
    tshape = ctx["target__shape"]
    tdtype = _resolve_dtype(ctx["target__dtype"])
    wshape = ctx["weight__shape"]
    wdtype = _resolve_dtype(ctx["weight__dtype"])
    return {
        "target": torch.rand(tshape, dtype=tdtype, device=device),
        "weight": torch.rand(wshape, dtype=wdtype, device=device),
    }
